#!ibl edition=2
$t = [self:trigger]{op:"list"}
$w = $t.items >> [table:filter]{where:($r)=> $r.name == "forage_resurvey_부동산"}
$h = [self:trigger]{op:"history", id:$w[0].id, limit:50}
return {run_count:$w[0].run_count, history_rows:len($h.items), shown:$h.items >> [table:select]{columns:["time","success"]}}

#!ibl edition=2
$m = [sense:realty]{source:"naver", region:"청주", deal:"lease"} >> [table:since]{key:"IT75_청주전세"}
[if: len($m.items) > 0] { [self:notify_user]{message:f"청주 새 전세 ${len($m.items)}건"} }

#!ibl edition=2
$rows = [{id:"a", title:"첫 글"},{id:"b", title:"둘째 글"}]
$n = $rows >> [table:since]{key:"IT75_피드"}
[if: len($n.items) > 0] { return {alert:true, n:len($n.items), titles:$n.items >> [table:select]{columns:["title"]}} } [else] { return {alert:false, note:get($n, "note", "")} }

